import{_ as a,o as i,c as s,a2 as e}from"./chunks/framework.BYgiQ6KE.js";const n="/angular-tutorial-site/assets/EP.18-migration-governance.B9k-FW1O.svg",k=JSON.parse('{"title":"EP.18 迁移不重写","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.18-migration-governance.md","filePath":"comics/EP.18-migration-governance.md","lastUpdated":1793863170000}'),o={name:"comics/EP.18-migration-governance.md"};function r(l,t,d,h,p,c){return i(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="ep-18-迁移不重写" tabindex="-1">EP.18 迁移不重写 <a class="header-anchor" href="#ep-18-迁移不重写" aria-label="Permalink to &quot;EP.18 迁移不重写&quot;">​</a></h1><p><img src="'+n+`" alt="EP.18 迁移不重写"></p><blockquote><p>对应正文：<a href="./../guide/part7/18-migration-governance">18-migration-governance</a>（1 迁移误区 / 2 六阶段路线 / 4 边界规则 / 6 版本治理 / 7 常见坑）· 配套示例：<code>routing-form</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：像素酱接到「三个月迁移完、停需求全部重写」的要求。一次性重写把风险集中到发布日，还留下了 <code>signal</code> 与 <code>BehaviorSubject</code> 两套状态。</li><li><strong>第 2 格</strong>：码叔给出六阶段路线——盘点依赖、升级工具链、结构迁移、收紧 DI 边界、领域逻辑下沉、最后清理过渡代码。</li><li><strong>第 3 格</strong>：标签君演示边界规则：UI → Facade → Domain 单向依赖，ESLint 阻止反向 import，公共 API 只从 <code>index.ts</code> 导出。</li><li><strong>第 4 格</strong>：码叔结案——<strong>先边界、后替换；能回滚的小步，才敢连续发布</strong>。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-一次性重写的代价" tabindex="-1">第 1 格 · 一次性重写的代价 <a class="header-anchor" href="#第-1-格-·-一次性重写的代价" aria-label="Permalink to &quot;第 1 格 · 一次性重写的代价&quot;">​</a></h3><p>「停需求三个月再上线」意味着：需求积压、风险集中在发布日、回滚成本极高。迁移真正难的不是换语法，而是边界与顺序。</p><p>双真源是常见后遗症：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">count </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> signal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">count$ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BehaviorSubject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>两套状态同时存在，谁先更新、谁是真值都说不清。</p><h3 id="第-2-格-·-六阶段路线" tabindex="-1">第 2 格 · 六阶段路线 <a class="header-anchor" href="#第-2-格-·-六阶段路线" aria-label="Permalink to &quot;第 2 格 · 六阶段路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>风险</th><th>可批量</th></tr></thead><tbody><tr><td>①</td><td>盘点依赖与阻塞点</td><td>低</td><td>否</td></tr><tr><td>②</td><td>升级工具链与主版本</td><td>中</td><td>是</td></tr><tr><td>③</td><td>结构与样式迁移</td><td>低</td><td>是</td></tr><tr><td>④</td><td>状态与 DI 边界收紧</td><td>中</td><td>否</td></tr><tr><td>⑤</td><td>领域逻辑下沉</td><td>高</td><td>否</td></tr><tr><td>⑥</td><td>清理过渡代码与双真源</td><td>低</td><td>是</td></tr></tbody></table><p>机械步骤先做，涉及语义的步骤后做；每一步都要能独立发布与回滚。</p><h3 id="第-3-格-·-边界规则" tabindex="-1">第 3 格 · 边界规则 <a class="header-anchor" href="#第-3-格-·-边界规则" aria-label="Permalink to &quot;第 3 格 · 边界规则&quot;">​</a></h3><p>依赖方向只能单向：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UI / 组件  →  Facade（用例编排）</span></span>
<span class="line"><span>Facade     →  Domain（实体、规则、纯函数）</span></span>
<span class="line"><span>Domain     ↛  UI</span></span></code></pre></div><p>用 ESLint <code>boundaries</code> 或 <code>import/no-restricted-paths</code> 把规则固化，而不是靠代码评审自觉。公共 API 从 <code>index.ts</code> 导出，内部文件禁止被跨模块直接引用。</p><h3 id="第-4-格-·-版本治理" tabindex="-1">第 4 格 · 版本治理 <a class="header-anchor" href="#第-4-格-·-版本治理" aria-label="Permalink to &quot;第 4 格 · 版本治理&quot;">​</a></h3><ul><li>Angular 主版本、Node 版本、构建器版本写进 <code>package.json</code> 与锁文件；</li><li>升级前先跑兼容性 lint 与全量测试，再合并；</li><li>过渡期允许适配层，但必须登记负责人与删除时间；</li><li>每完成一个阶段，删除对应的过渡代码，避免「临时方案」永久化。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../guide/part7/18-migration-governance#7-常见坑">常见坑表格</a></p></blockquote><ol><li>一次性重写 → <strong>风险集中到发布日，改为可回滚的小步</strong>；</li><li>保留双真源 → <strong>signal 与 Subject 长期并存，清理阶段必须删除一套</strong>；</li><li>版本不写进锁文件 → <strong>环境间行为漂移，升级不可复现</strong>；</li><li>只在评审里口头约定边界 → <strong>换个 reviewer 就失守，改用 lint 固化</strong>；</li><li>过渡代码没有负责人与期限 → <strong>临时方案永久化</strong>。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>为什么「停需求重写」通常不是好方案？——<strong>它把风险集中到单次发布，期间需求积压、回滚困难；分阶段小步迁移可以每步发布、每步回滚，问题定位也更早</strong>。</li><li>双真源为什么必须清理？——<strong>两套状态同时存在会产生更新顺序与真值归属不清，长期造成数据不一致与重复渲染；迁移结束时只能保留一套</strong>。</li><li>边界规则为什么要用 lint 而不是评审？——<strong>评审依赖人的记忆与状态，人员变化就会失守；lint 把规则变成可执行、可重复的门禁</strong>。</li></ol>`,25)])])}const u=a(o,[["render",r]]);export{k as __pageData,u as default};
